import GitHubIcon from '@material-ui/icons/GitHub'
import LinkedInIcon from '@material-ui/icons/LinkedIn'
import { about } from '../../portfolio'
import './About.css'
import keyblade from '../../Images/keyblade.png'


const About = () => {
  const { name, role, description, resume, showResume, social, picture } = about

  let imageSrc = ''
  if (picture) {
    if (picture.startsWith('http')) {
      imageSrc = picture
    } else if (picture.startsWith('/')) {
      imageSrc = `${process.env.PUBLIC_URL}${picture}`
    } else {
      imageSrc = `${process.env.PUBLIC_URL}/images/${picture}`
    }
  }
   
  return (
    <div className='about center'>
      <div className='about__header'>
        {picture && (
          <img
            src={imageSrc}
            alt={name}
            className='about__picture'
            width='180'
            height='180'
            decoding='async'
          />
        )}

        <div className='about__intro'>
          {name && (
            <h1>
              <span className='about__name'>{name}.</span>
            </h1>
          )}

          {role && <h2 className='about__role'>{role}</h2>}
          <p className='about__desc'>{description}</p>
        </div>
      </div>

      <div className='about__contact'>
  {/* LEFT button */}
  {showResume && resume && (
    <a
      href={resume}
      target='_blank'
      rel='noopener noreferrer'
      className='btn btn--outline'
    >
      <img src={keyblade} alt='' className='about__keyblade' />
      Resume
    </a>
  )}

  {/* MIDDLE icons */}
  <div className='about__social-icons'>
    {social && (
      <>
        {social.github && (
          <a
            href={social.github}
            aria-label='github'
            className='link link--icon'
            target='_blank'
            rel='noopener noreferrer'
          >
            <GitHubIcon />
          </a>
        )}
        {social.linkedin && (
          <a
            href={social.linkedin}
            aria-label='linkedin'
            className='link link--icon'
            target='_blank'
            rel='noopener noreferrer'
          >
            <LinkedInIcon />
          </a>
        )}
      </>
    )}
  </div>

  {/* RIGHT button */}
  {social && social.favouriteGames && (
    <a
      href={social.favouriteGames}
      target='_blank'
      rel='noopener noreferrer'
      className='btn btn--outline'
    >
      🎮 My Favourite Games
    </a>
  )}
</div>
    </div>
  )
}

export default About
